; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpc, starts in normal mode
; ============================================================

			org #4000

ntc_start:
			di
			ld (ntc_csp), sp
			ld hl, ntc_gstack_top
			ld (ntc_gsp), hl
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld ix, ntc_go
			jp ntc_plat_irqon		; interrupt handler for normal mode
ntc_go:
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_scrinit		; mode 1, ROMs off, clear screen

			; 2: GOSUB s1 : GOSUB s2 : PRINT
			dw kw_gosub_n, lbl_s1
			dw kw_gosub_n, lbl_s2
			dw kw_printnl

			; 3: GOSUB r1 : PRINT "r done"
			dw kw_gosub_n, lbl_r1
			dw kw_printzoscii
			dw glyph_72, glyph_20, glyph_64, glyph_6F, glyph_6E, glyph_65, 1, 0		; "r done\n"

			; 4: GOSUB g1 : PRINT "g done"
			dw kw_gosub_n, lbl_g1
			dw kw_printzoscii
			dw glyph_67, glyph_20, glyph_64, glyph_6F, glyph_6E, glyph_65, 1, 0		; "g done\n"

			; 5: n = 0 : GOSUB rec : PRINT "rec"; n
			dw kw_ztov, var_n
			dw kw_gosub_n, lbl_rec
			dw kw_printzoscii
			dw glyph_72, glyph_65, glyph_63, 0		; "rec"
			dw kw_printint, var_n
			dw kw_printnl

			; 6: END
			dw kw_stop

			; 7: s1: PRINT "1";
lbl_s1:
			dw kw_printzoscii
			dw glyph_31, 0		; "1"

			; 8: s2: PRINT "2"; : RETURN
lbl_s2:
			dw kw_printzoscii
			dw glyph_32, 0		; "2"
			dw kw_return_n

			; 9: r1: PRINT "r1 "; : GOTO r1b
lbl_r1:
			dw kw_printzoscii
			dw glyph_72, glyph_31, glyph_20, 0		; "r1 "
			dw lbl_r1b_go

			; 10: r1x: RETURN
lbl_r1x:
			dw kw_return_n

			; 11: g1: PRINT "g1 "; : RETURN
lbl_g1:
			dw kw_printzoscii
			dw glyph_67, glyph_31, glyph_20, 0		; "g1 "
			dw kw_return_n

			; 12: r1b: PRINT "r1b "; : RETURN
lbl_r1b:
			dw kw_printzoscii
			dw glyph_72, glyph_31, glyph_62, glyph_20, 0		; "r1b "
			dw kw_return_n

			; 13: rec: n = n + 1 : IF n < 3 THEN GOSUB rec
lbl_rec:
			dw kw_inc, var_n
			dw kw_scpltvl, var_n, 3
			dw kw_goto_iffalse_n, if1_1
			dw kw_gosub_n, lbl_rec
if1_1:

			; 14: RETURN
			dw kw_return_n

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

lbl_r1b_go:			ld sp, lbl_r1b
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0

; ============================================================
; ZOSCII glyphs - each points at its 8 byte bitmap in ntc_font
; ============================================================

glyph_20			equ ntc_font + 0		; " "
glyph_31			equ ntc_font + 136		; "1"
glyph_32			equ ntc_font + 144		; "2"
glyph_62			equ ntc_font + 528		; "b"
glyph_63			equ ntc_font + 536		; "c"
glyph_64			equ ntc_font + 544		; "d"
glyph_65			equ ntc_font + 552		; "e"
glyph_67			equ ntc_font + 568		; "g"
glyph_6E			equ ntc_font + 624		; "n"
glyph_6F			equ ntc_font + 632		; "o"
glyph_72			equ ntc_font + 656		; "r"

; ============================================================
; Keyword library (used)
; ============================================================

;## ntc_data @shared
; ------------------------------------------------------------
; Scratch space
; ------------------------------------------------------------
ntc_next:		ret				; IX target that continues the thread
ntc_csp:		dw 0			; caller SP, for kw_stop (and the normal mode stack)
ntc_ip:			dw 0			; normal mode: thread position while out of the thread
ntc_ticks:		dw 0			; interrupt count (normal mode, platform handler)
ntc_gnlo:		db 0			; ntc_getn: low byte
ntc_nmode:		db 0			; 1 = running in normal mode (waits let interrupts in)
ntc_mode:		db 0			; div mode 0=quotient 1=remainder
ntc_sgnq:		db 0			; quotient sign (bit 7)
ntc_sgnr:		db 0			; remainder sign (bit 7)
ntc_lead:		db 0			; printint: digit seen
ntc_icnt:		db 0			; gets: chars typed
ntc_sptr:		dw 0			; printbuf: text pointer
ntc_iptr:		dw 0			; gets: buffer pointer
ntc_ilink:		dw 0			; gets: where to go when done
ntc_ivar:		dw 0			; inputint / inkey: dest var
ntc_aptr:		dw 0			; atoi: text pointer
ntc_numbuf:		ds 12			; printint / long print: digits
ntc_inbuf:		ds 41			; inputint: typed text

;## ntc_gstack
; ------------------------------------------------------------
; GOSUB return stack (grows down, 64 levels)
; ------------------------------------------------------------
ntc_gsp:		dw ntc_gstack_top
ntc_gstack:		ds 128
ntc_gstack_top:

; ============================================================
; Flow
; ============================================================

;## kw_stop ntc_data ntc_plat_exit @shared
kw_stop:
			ld ix, ntc_stop_back
			jp ntc_plat_exit
ntc_stop_back:
			ld sp, (ntc_csp)
			ei
			ret

;## ntc_xn ntc_data @shared
; normal mode "next": every normal mode keyword ends here (its ret
; became jp ntc_xn). Thread position to ntc_ip, real stack, one
; instruction with interrupts on, then back into the thread.
ntc_xn:
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			nop					; an interrupt can be taken here
			di
			ld sp, (ntc_ip)
			ret

;## kw_goto_iffalse (normal mode copy)
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse_n:
			pop hl
			jp z, ntc_xn
			ld sp, hl
			jp ntc_xn

;## kw_gosub (normal mode copy) ntc_gstack
;kw_gosub, <label>  - return lands on the word after the label
kw_gosub_n:
			pop bc
			ld hl, 0
			add hl, sp
			ex de, hl
			ld hl, (ntc_gsp)
			dec hl
			ld (hl), d
			dec hl
			ld (hl), e
			ld (ntc_gsp), hl
			ld h, b
			ld l, c
			ld sp, hl
			jp ntc_xn

;## kw_return (normal mode copy) ntc_gstack
;kw_return
kw_return_n:
			ld hl, (ntc_gsp)
			ld e, (hl)
			inc hl
			ld d, (hl)
			inc hl
			ld (ntc_gsp), hl
			ex de, hl
			ld sp, hl
			jp ntc_xn

;## kw_ztov
;kw_ztov, <destvar>
kw_ztov:
			xor a
			pop hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret

;## kw_inc
;kw_inc, <var>
kw_inc:
			pop hl
			inc (hl)
			ret nz
			inc hl
			inc (hl)
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## ntc_printbuf ntc_data ntc_font ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			sub 32
			jr c, ntc_pb_bad
			cp 95
			jr c, ntc_pb_ok
ntc_pb_bad:
			ld a, '?' - 32
ntc_pb_ok:
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld de, ntc_font
			add hl, de
			ex de, hl
			ld ix, ntc_printbuf
			jp ntc_plat_putglyph

;## kw_printzoscii ntc_data ntc_font ntc_plat_screen
;kw_printzoscii / dw glyph, glyph, ..., 0  - ZOSCII text inline in the thread
;  each word points at an 8 byte glyph bitmap. 1 = newline, 0 = end.
kw_printzoscii:
			pop de
			ld a, d
			or a
			jr z, ntc_pz_ctl
			ld ix, kw_printzoscii
			jp ntc_plat_putglyph
ntc_pz_ctl:
			or e
			ret z
			ld ix, kw_printzoscii
			jp ntc_plat_newline

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_scrinit ntc_data ntc_plat_screen
;kw_scrinit  - first word of any program that prints or reads keys:
;  mode 1, ROMs off, clear screen
kw_scrinit:
			ld a, 1
			ld ix, ntc_next
			jp ntc_plat_mode

;## ntc_font
; 8x8 font, chars 32-126, 8 bytes each, bit 7 = leftmost pixel
; from font8x8_basic by Daniel Hepper (public domain, IBM VGA based)
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:
			db #00, #00, #00, #00, #00, #00, #00, #00		; 32  
			db #18, #3C, #3C, #18, #18, #00, #18, #00		; 33 !
			db #6C, #6C, #00, #00, #00, #00, #00, #00		; 34 "
			db #6C, #6C, #FE, #6C, #FE, #6C, #6C, #00		; 35 #
			db #30, #7C, #C0, #78, #0C, #F8, #30, #00		; 36 $
			db #00, #C6, #CC, #18, #30, #66, #C6, #00		; 37 %
			db #38, #6C, #38, #76, #DC, #CC, #76, #00		; 38 &
			db #60, #60, #C0, #00, #00, #00, #00, #00		; 39 '
			db #18, #30, #60, #60, #60, #30, #18, #00		; 40 (
			db #60, #30, #18, #18, #18, #30, #60, #00		; 41 )
			db #00, #66, #3C, #FF, #3C, #66, #00, #00		; 42 *
			db #00, #30, #30, #FC, #30, #30, #00, #00		; 43 +
			db #00, #00, #00, #00, #00, #30, #30, #60		; 44 ,
			db #00, #00, #00, #FC, #00, #00, #00, #00		; 45 -
			db #00, #00, #00, #00, #00, #30, #30, #00		; 46 .
			db #06, #0C, #18, #30, #60, #C0, #80, #00		; 47 /
			db #7C, #C6, #CE, #DE, #F6, #E6, #7C, #00		; 48 0
			db #30, #70, #30, #30, #30, #30, #FC, #00		; 49 1
			db #78, #CC, #0C, #38, #60, #CC, #FC, #00		; 50 2
			db #78, #CC, #0C, #38, #0C, #CC, #78, #00		; 51 3
			db #1C, #3C, #6C, #CC, #FE, #0C, #1E, #00		; 52 4
			db #FC, #C0, #F8, #0C, #0C, #CC, #78, #00		; 53 5
			db #38, #60, #C0, #F8, #CC, #CC, #78, #00		; 54 6
			db #FC, #CC, #0C, #18, #30, #30, #30, #00		; 55 7
			db #78, #CC, #CC, #78, #CC, #CC, #78, #00		; 56 8
			db #78, #CC, #CC, #7C, #0C, #18, #70, #00		; 57 9
			db #00, #30, #30, #00, #00, #30, #30, #00		; 58 :
			db #00, #30, #30, #00, #00, #30, #30, #60		; 59 ;
			db #18, #30, #60, #C0, #60, #30, #18, #00		; 60 <
			db #00, #00, #FC, #00, #00, #FC, #00, #00		; 61 =
			db #60, #30, #18, #0C, #18, #30, #60, #00		; 62 >
			db #78, #CC, #0C, #18, #30, #00, #30, #00		; 63 ?
			db #7C, #C6, #DE, #DE, #DE, #C0, #78, #00		; 64 @
			db #30, #78, #CC, #CC, #FC, #CC, #CC, #00		; 65 A
			db #FC, #66, #66, #7C, #66, #66, #FC, #00		; 66 B
			db #3C, #66, #C0, #C0, #C0, #66, #3C, #00		; 67 C
			db #F8, #6C, #66, #66, #66, #6C, #F8, #00		; 68 D
			db #FE, #62, #68, #78, #68, #62, #FE, #00		; 69 E
			db #FE, #62, #68, #78, #68, #60, #F0, #00		; 70 F
			db #3C, #66, #C0, #C0, #CE, #66, #3E, #00		; 71 G
			db #CC, #CC, #CC, #FC, #CC, #CC, #CC, #00		; 72 H
			db #78, #30, #30, #30, #30, #30, #78, #00		; 73 I
			db #1E, #0C, #0C, #0C, #CC, #CC, #78, #00		; 74 J
			db #E6, #66, #6C, #78, #6C, #66, #E6, #00		; 75 K
			db #F0, #60, #60, #60, #62, #66, #FE, #00		; 76 L
			db #C6, #EE, #FE, #FE, #D6, #C6, #C6, #00		; 77 M
			db #C6, #E6, #F6, #DE, #CE, #C6, #C6, #00		; 78 N
			db #38, #6C, #C6, #C6, #C6, #6C, #38, #00		; 79 O
			db #FC, #66, #66, #7C, #60, #60, #F0, #00		; 80 P
			db #78, #CC, #CC, #CC, #DC, #78, #1C, #00		; 81 Q
			db #FC, #66, #66, #7C, #6C, #66, #E6, #00		; 82 R
			db #78, #CC, #E0, #70, #1C, #CC, #78, #00		; 83 S
			db #FC, #B4, #30, #30, #30, #30, #78, #00		; 84 T
			db #CC, #CC, #CC, #CC, #CC, #CC, #FC, #00		; 85 U
			db #CC, #CC, #CC, #CC, #CC, #78, #30, #00		; 86 V
			db #C6, #C6, #C6, #D6, #FE, #EE, #C6, #00		; 87 W
			db #C6, #C6, #6C, #38, #38, #6C, #C6, #00		; 88 X
			db #CC, #CC, #CC, #78, #30, #30, #78, #00		; 89 Y
			db #FE, #C6, #8C, #18, #32, #66, #FE, #00		; 90 Z
			db #78, #60, #60, #60, #60, #60, #78, #00		; 91 [
			db #C0, #60, #30, #18, #0C, #06, #02, #00		; 92 backslash
			db #78, #18, #18, #18, #18, #18, #78, #00		; 93 ]
			db #10, #38, #6C, #C6, #00, #00, #00, #00		; 94 ^
			db #00, #00, #00, #00, #00, #00, #00, #FF		; 95 _
			db #30, #30, #18, #00, #00, #00, #00, #00		; 96 `
			db #00, #00, #78, #0C, #7C, #CC, #76, #00		; 97 a
			db #E0, #60, #60, #7C, #66, #66, #DC, #00		; 98 b
			db #00, #00, #78, #CC, #C0, #CC, #78, #00		; 99 c
			db #1C, #0C, #0C, #7C, #CC, #CC, #76, #00		; 100 d
			db #00, #00, #78, #CC, #FC, #C0, #78, #00		; 101 e
			db #38, #6C, #60, #F0, #60, #60, #F0, #00		; 102 f
			db #00, #00, #76, #CC, #CC, #7C, #0C, #F8		; 103 g
			db #E0, #60, #6C, #76, #66, #66, #E6, #00		; 104 h
			db #30, #00, #70, #30, #30, #30, #78, #00		; 105 i
			db #0C, #00, #0C, #0C, #0C, #CC, #CC, #78		; 106 j
			db #E0, #60, #66, #6C, #78, #6C, #E6, #00		; 107 k
			db #70, #30, #30, #30, #30, #30, #78, #00		; 108 l
			db #00, #00, #CC, #FE, #FE, #D6, #C6, #00		; 109 m
			db #00, #00, #F8, #CC, #CC, #CC, #CC, #00		; 110 n
			db #00, #00, #78, #CC, #CC, #CC, #78, #00		; 111 o
			db #00, #00, #DC, #66, #66, #7C, #60, #F0		; 112 p
			db #00, #00, #76, #CC, #CC, #7C, #0C, #1E		; 113 q
			db #00, #00, #DC, #76, #66, #60, #F0, #00		; 114 r
			db #00, #00, #7C, #C0, #78, #0C, #F8, #00		; 115 s
			db #10, #30, #7C, #30, #30, #34, #18, #00		; 116 t
			db #00, #00, #CC, #CC, #CC, #CC, #76, #00		; 117 u
			db #00, #00, #CC, #CC, #CC, #78, #30, #00		; 118 v
			db #00, #00, #C6, #D6, #FE, #FE, #6C, #00		; 119 w
			db #00, #00, #C6, #6C, #38, #6C, #C6, #00		; 120 x
			db #00, #00, #CC, #CC, #CC, #7C, #0C, #F8		; 121 y
			db #00, #00, #FC, #98, #30, #64, #FC, #00		; 122 z
			db #1C, #30, #30, #E0, #30, #30, #1C, #00		; 123 {
			db #18, #18, #18, #00, #18, #18, #18, #00		; 124 |
			db #E0, #30, #30, #1C, #30, #30, #E0, #00		; 125 }
			db #76, #DC, #00, #00, #00, #00, #00, #00		; 126 ~

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode
ntc_sinit:		db 0			; 1 once the screen is set up
ntc_sbpc:		db 2			; bytes per char  \
ntc_scols:		db 40			; columns          | from ntc_modetab
ntc_smask:		db #F0			; pen 1 pixel mask |
ntc_sshift:		db 4			; glyph bits/byte /
ntc_noadv:		db 0			; 1 = draw without moving the cursor
ntc_pgrow:		db 0			; draw / scroll counter
ntc_pgaddr:		dw 0			; draw / scroll address
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 10			; matrix this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_modetab:	db 4, 20, #C0, 2		; mode 0
				db 2, 40, #F0, 4		; mode 1
				db 1, 80, #FF, 8		; mode 2

;## ntc_plat_screen ntc_plat_data ntc_font
; ------------------------------------------------------------
; ntc_plat_putglyph - DE = 8 byte glyph, draw at the cursor, move on
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld a, (ntc_cury)
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			add hl, hl
			ld b, h
			ld c, l
			add hl, hl
			add hl, hl
			add hl, bc			; HL = row * 80
			ld a, (ntc_sbpc)
			ld b, a
			ld a, (ntc_curx)
			ld c, a
			xor a
ntc_pg_mul:
			add a, c
			djnz ntc_pg_mul		; A = column * bytes per char
			ld c, a
			ld b, #C0
			add hl, bc			; HL = #C000 + row*80 + col*bpc
			ld a, 8
ntc_pg_row:
			ld (ntc_pgrow), a
			ld (ntc_pgaddr), hl
			ld a, (de)
			inc de
			ld c, a
			ld a, (ntc_sbpc)
			ld b, a
ntc_pg_byte:
			ld a, (ntc_smask)
			and c
			ld (hl), a
			inc hl
			ld a, (ntc_sshift)
			sla c
			sla c
			cp 4
			jr c, ntc_pg_shifted
			sla c
			sla c
ntc_pg_shifted:
			djnz ntc_pg_byte
			ld hl, (ntc_pgaddr)
			ld bc, #800
			add hl, bc
			ld a, (ntc_pgrow)
			dec a
			jr nz, ntc_pg_row
			ld a, (ntc_noadv)
			or a
			jr nz, ntc_pg_noadv
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_plat_newline
			jp (ix)
ntc_pg_noadv:
			xor a
			ld (ntc_noadv), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom
; ------------------------------------------------------------
ntc_plat_newline:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-24 up one, clear row 24
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, 24
			ld (ntc_cury), a
			ld hl, #C000
			ld a, 8
ntc_sc_line:
			ld (ntc_pgrow), a
			ld (ntc_pgaddr), hl
			ld d, h
			ld e, l
			ld bc, 80
			add hl, bc
			ld bc, 24 * 80
			ldir
			ld h, d
			ld l, e
			ld (hl), 0
			inc de
			ld bc, 79
			ldir
			ld hl, (ntc_pgaddr)
			ld bc, #800
			add hl, bc
			ld a, (ntc_pgrow)
			dec a
			jr nz, ntc_sc_line
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_backspace - cursor back one and blank that cell
; ------------------------------------------------------------
ntc_plat_backspace:
			ld a, (ntc_curx)
			or a
			jr nz, ntc_bs_col
			ld a, (ntc_cury)
			or a
			jr z, ntc_bs_none
			dec a
			ld (ntc_cury), a
			ld a, (ntc_scols)
ntc_bs_col:
			dec a
			ld (ntc_curx), a
			ld a, 1
			ld (ntc_noadv), a
			ld de, ntc_font		; space
			jp ntc_plat_putglyph
ntc_bs_none:
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - clear screen memory, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, #C000
			ld de, #C001
			ld bc, #3FFF
			ld (hl), 0
			ldir
			xor a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_mode - A = mode (0-2, 3 = 2). Gate array mode with both
; ROMs off, set text layout, clear screen
; ------------------------------------------------------------
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld (ntc_smode), a
			ld c, a
			or #8C
			ld b, #7F
			out (c), a
			ld a, 1
			ld (ntc_sinit), a
			ld a, c
			add a, a
			add a, a
			ld c, a
			ld b, 0
			ld hl, ntc_modetab
			add hl, bc
			ld de, ntc_sbpc
			ld bc, 4
			ldir
			jp ntc_plat_cls

; ------------------------------------------------------------
; ntc_plat_locate - H = column, L = row, 1 based, kept on screen
; ------------------------------------------------------------
ntc_plat_locate:
			ld a, h
			or a
			jr z, ntc_lc_x0
			dec a
ntc_lc_x0:
			ld c, a
			ld a, (ntc_scols)
			dec a
			cp c
			jr c, ntc_lc_xmax
			ld a, c
ntc_lc_xmax:
			ld (ntc_curx), a
			ld a, l
			or a
			jr z, ntc_lc_y0
			dec a
ntc_lc_y0:
			cp 25
			jr c, ntc_lc_ymax
			ld a, 24
ntc_lc_ymax:
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_irq ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_irqon - put the interrupt handler at #38 (IM 1)
; ------------------------------------------------------------
ntc_plat_irqon:
			ld hl, (#0038)
			ld (ntc_irqold), hl
			ld a, (#003A)
			ld (ntc_irqold + 2), a
			ld a, #C3			; jp ntc_irq
			ld (#0038), a
			ld hl, ntc_irq
			ld (#0039), hl
			ld a, 1
			ld (ntc_irqset), a
			jp (ix)

; the handler: runs on the real stack, between keywords. Counts ticks
; (300 a second). No push - AF goes to AF', HL to RAM.
ntc_irq:
			ex af, af'
			ld (ntc_irqhl), hl
			ld hl, (ntc_ticks)
			inc hl
			ld (ntc_ticks), hl
			ld hl, (ntc_irqhl)
			ex af, af'
			ei
			ret

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - before returning to the caller: interrupt handler
; out, upper ROM back on (lower off) if the screen was set up
; ------------------------------------------------------------
ntc_plat_exit:
			ld a, (ntc_irqset)
			or a
			jr z, ntc_ex_rom
			ld hl, (ntc_irqold)
			ld (#0038), hl
			ld a, (ntc_irqold + 2)
			ld (#003A), a
			xor a
			ld (ntc_irqset), a
ntc_ex_rom:
			ld a, (ntc_sinit)
			or a
			jr z, ntc_ex_done
			ld a, (ntc_smode)
			or #84
			ld b, #7F
			out (c), a
ntc_ex_done:
			jp (ix)

